algorithms.pseudocode:
function ColumnSeparator(m, n, c):
    require 0 <= c <= n
    return [ (i, c) for i in 0..m ]      # one vertex per row
function MinCutValue(m, n):
    return m + 1                          # the height

function RowPaths(m, n):
    paths = []
    for i in 0..m:
        paths.append([ (i, j) for j in 0..n ])
    return paths
function MaxDisjointPathsValue(m, n):
    return m + 1

function DiscreteIVTWitness(walk, label, c):
    # precondition: label(walk[0]) <= c <= label(walk[-1])
    #               |label(walk[k+1]) - label(walk[k])| <= 1
    for v in walk:
        if label(v) == c:
            return v
    return None   # unreachable under the precondition
